SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(d),'object',to_jsonb(pg_identify_object(d.classid,d.objid,d.objsubid)),'reference',to_jsonb(pg_identify_object(d.refclassid,d.refobjid,0))) ORDER BY d.dbid,d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.deptype),'[]'::jsonb) AS payload FROM pg_shdepend d WHERE d.dbid=0 OR d.dbid=(SELECT oid FROM pg_database WHERE datname=current_database())) AS capture